import{_ as t,o as s,c as e,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const i="/bzygq/assets/quesion_imgs_image_1769735008515_0_1769735008524_321.D6dY-oZU.png",o="/bzygq/assets/quesion_imgs_image_1769735009413_1_1769735009419_863.CffPciQ0.png",n="/bzygq/assets/quesion_imgs_image_1769735009930_2_1769735009938_252.XBJIy2JD.png",l="/bzygq/assets/quesion_imgs_image_1769735010947_3_1769735010954_106.BWAIMO2O.png",_="/bzygq/assets/quesion_imgs_image_1769735011540_4_1769735011547_953.udF5lUly.png",g="/bzygq/assets/quesion_imgs_image_1769735012636_5_1769735012640_255.BwNKC1ML.png",p="/bzygq/assets/quesion_imgs_image_1769735013218_6_1769735013224_119.BRBJp8xE.png",m="/bzygq/assets/quesion_imgs_image_1769735014195_7_1769735014205_256.DsTdtX8I.png",h="/bzygq/assets/quesion_imgs_image_1769735015133_8_1769735015140_967.CNs2iFCu.png",c="/bzygq/assets/quesion_imgs_image_1769735016171_9_1769735016175_426.D2Uu8IFP.png",d="/bzygq/assets/quesion_imgs_image_1769735016615_10_1769735016618_571.C8N98SjN.png",u="/bzygq/assets/quesion_imgs_image_1769735017269_11_1769735017271_641.CgjUr48C.png",b="/bzygq/assets/quesion_imgs_image_1769735017784_12_1769735017787_78.CfNFx8dv.png",q="/bzygq/assets/quesion_imgs_image_1769735018632_13_1769735018635_24.Kf5p6VXq.png",C="/bzygq/assets/quesion_imgs_image_1769735019037_14_1769735019041_151.CyVdHqhR.png",k="/bzygq/assets/quesion_imgs_image_1769735019722_15_1769735019726_547.aPTbtzTX.png",P="/bzygq/assets/quesion_imgs_image_1769735016171_9_1769735016175_426.D2Uu8IFP.png",B="/bzygq/assets/quesion_imgs_image_1769735020869_17_1769735020879_830.Ul6dKNTb.png",A="/bzygq/assets/quesion_imgs_image_1769735021804_18_1769735021812_82.CrgWbeQO.png",x="/bzygq/assets/quesion_imgs_image_1769735022794_19_1769735022806_113.Ch7QP7dg.png",y="/bzygq/assets/quesion_imgs_image_1769735023929_20_1769735023940_65.DSnzd4iC.png",D="/bzygq/assets/quesion_imgs_image_1769735025633_21_1769735025641_440.BGzQlIpm.png",f="/bzygq/assets/quesion_imgs_image_1769735026949_22_1769735026960_428.CS41wkCN.png",S="/bzygq/assets/quesion_imgs_image_1769735028510_23_1769735028518_403.BBciTg5-.png",U=JSON.parse('{"title":"2、图的最小生成树","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/数据结构/7、图/2、图的最小生成树.md","filePath":"科技岗专业课/数据结构/7、图/2、图的最小生成树.md","lastUpdated":1788883925000}'),z={name:"科技岗专业课/数据结构/7、图/2、图的最小生成树.md"};function K(T,a,F,E,M,N){return s(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="_2、图的最小生成树" tabindex="-1">2、图的最小生成树 <a class="header-anchor" href="#_2、图的最小生成树" aria-label="Permalink to &quot;2、图的最小生成树&quot;">​</a></h1><p><strong>图的最小生成树</strong></p><p>简单来说，图的最小生成树就是帮你解决 “<strong>用最少成本把所有点连起来</strong>” 的问题 —— 比如修公路（城市 = 顶点，公路 = 边，造价 = 权重），要让所有城市互通，还得总造价最低，这时候找的就是最小生成树（还不能有环路，环路等于多花钱修重复路）。</p><p>但是，图的最小生成树的存在必须有一个前置条件，那就是图必须是连通的，因此，本文从连通图开始逐步深入介绍什么是图的最小生成树，以及找图的最小生成树的两种算法——Prim算法和Kruska&#39;s算法。</p><h2 id="生成树的前置知识——连通图" tabindex="-1">生成树的前置知识——连通图 <a class="header-anchor" href="#生成树的前置知识——连通图" aria-label="Permalink to &quot;生成树的前置知识——连通图&quot;">​</a></h2><h2 id="非连通图-unconnected-graph" tabindex="-1">非连通图（UnConnected Graph） <a class="header-anchor" href="#非连通图-unconnected-graph" aria-label="Permalink to &quot;非连通图（UnConnected Graph）&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>非连通图（Disconnected Graph）是指一个图中存在至少两个顶点，它们之间没有路径相连。换句话说，在非连通图中，至少存在一个顶点对 (u,v) ，使得从 u 到 v没有路径。非连通图可以分为多个连通分量，每个连通分量都是一个连通子图。</p><h2 id="连通图-connected-graph" tabindex="-1">连通图（Connected Graph） <a class="header-anchor" href="#连通图-connected-graph" aria-label="Permalink to &quot;连通图（Connected Graph）&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>连通图是指在一个无向图中，任意两个顶点之间都存在至少一条路径相连的图。换句话说，从图中的任意一个顶点出发，都可以通过图中的边到达图中的其他任何一个顶点。连通图的特点是没有孤立的顶点，且整个图作为一个整体是连通的。</p><h2 id="连通子图-connected-subgraph" tabindex="-1">连通子图（Connected Subgraph） <a class="header-anchor" href="#连通子图-connected-subgraph" aria-label="Permalink to &quot;连通子图（Connected Subgraph）&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>连通子图是指原图的一个子集，这个子集本身构成一个连通图。也就是说，如果从原图中选择一部分顶点及其相关的边，这些顶点和边所组成的图如果仍然是连通的，那么这个新的图就是原图的一个连通子图。需要注意的是，连通子图可以是原图本身，也可以是原图的一个部分。</p><h2 id="极大连通子图-maximal-connected-subgraph" tabindex="-1">极大连通子图（Maximal Connected Subgraph） <a class="header-anchor" href="#极大连通子图-maximal-connected-subgraph" aria-label="Permalink to &quot;极大连通子图（Maximal Connected Subgraph）&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>极大连通子图是指一个连通子图，它不能通过添加更多的顶点和边来扩展，同时仍然保持连通性。换句话说，如果再向这个子图中添加任何一个不属于当前子图的顶点或边，这个子图就会失去连通性。</p><h2 id="极小连通子图-minimal-connected-subgraph" tabindex="-1">极小连通子图（Minimal Connected Subgraph） <a class="header-anchor" href="#极小连通子图-minimal-connected-subgraph" aria-label="Permalink to &quot;极小连通子图（Minimal Connected Subgraph）&quot;">​</a></h2><p><img src="'+_+'" alt=""></p><p>极小连通子图是指一个连通子图，它不能通过删除任何一条边来保持连通性。换句话说，如果从这个子图中删除任何一条边，子图就会变得不连通。</p><h2 id="强连通图-strongly-connected-graph-scc" tabindex="-1">强连通图（Strongly Connected Graph, SCC） <a class="header-anchor" href="#强连通图-strongly-connected-graph-scc" aria-label="Permalink to &quot;强连通图（Strongly Connected Graph, SCC）&quot;">​</a></h2><p><img src="'+g+'" alt=""></p><p>在图论中，强连通图（Strongly Connected Graph）是一个有向图中的一个重要概念。与无向图的连通性不同，强连通图强调的是有向图中顶点之间的双向可达性。具体来说，强连通图是指在一个有向图中，任意两个顶点 <em>u</em> 和 <em>v</em> 之间都存在从 <em>u</em> 到 <em>v</em> 和从 <em>v</em> 到 <em>u</em> 的有向路径。换句话说，从图中的任意一个顶点出发，都可以通过图中的有向边到达图中的其他任何一个顶点，并且反过来也成立。</p><h2 id="强连通分量-strongly-connected-component-scc" tabindex="-1">强连通分量（Strongly Connected Component, SCC） <a class="header-anchor" href="#强连通分量-strongly-connected-component-scc" aria-label="Permalink to &quot;强连通分量（Strongly Connected Component, SCC）&quot;">​</a></h2><p><img src="'+p+'" alt=""></p><p>如果一个有向图不是强连通的，它可以被分解成若干个强连通分量。强连通分量是指图中最大的子图，这些子图内部是强连通的，但与其他子图之间没有这样的双向可达性。</p><h2 id="连通图的最小生成树" tabindex="-1">连通图的最小生成树 <a class="header-anchor" href="#连通图的最小生成树" aria-label="Permalink to &quot;连通图的最小生成树&quot;">​</a></h2><p><img src="'+m+'" alt=""></p><p>连通图的生成树（Spanning Tree）是指一个无向连通图的一个子图，它是一棵树，包含了原图中的所有顶点，并且是原图的一个极小连通子图，也就是说，它恰好有足够多的边来保证所有顶点都是连通的，但又没有多余的边形成环路。具体来说，如果一个连通图有 n个顶点，那么它的生成树将有 n−1条边。生成树的几个关键特性包括：</p><ul><li>连通性：生成树必须保持原图的连通性，即在生成树中可以从任意一个顶点到达其他任何一个顶点。</li><li>无环：生成树不能包含任何环路。</li><li>极小性：生成树是连通的，但是删除任何一条边都会使图变得不连通；同样地，添加任何一条不在生成树中的原图的边都会产生一个环。</li></ul><p>在实际应用中，生成树的概念非常重要，尤其是在网络设计、路径规划等领域。例如，在设计通信网络时，生成树可以帮助确定一种连接所有节点的最经济的方式，避免了不必要的冗余连接。</p><p>此外，对于带权图（每条边都有一个关联的数值，称为权重），还有一种特殊的生成树——<strong>最小生成树</strong>（Minimum Spanning Tree, MST），它是在所有可能的生成树中总权重最小的那一个。最小生成树在很多实际问题中有着广泛的应用，比如在电力网络、交通网络等基础设施的设计和优化中。</p><p><img src="'+h+'" alt=""></p><p>要找到一个无向连通图的最小生成树（Minimum Spanning Tree, MST），可以使用几种经典的算法，比如普里姆算法（Prim&#39;s Algorithm）或者克鲁斯卡尔算法（Kruskal&#39;s Algorithm）。这两种算法都能有效地找到一个图的最小生成树，即一个包含图中所有顶点且总权重最小的连通子图。</p><h2 id="普里姆算法-prim-s-algorithm" tabindex="-1">普里姆算法 (Prim&#39;s Algorithm) <a class="header-anchor" href="#普里姆算法-prim-s-algorithm" aria-label="Permalink to &quot;普里姆算法 (Prim&#39;s Algorithm)&quot;">​</a></h2><h2 id="什么是prim算法" tabindex="-1">什么是Prim算法？ <a class="header-anchor" href="#什么是prim算法" aria-label="Permalink to &quot;什么是Prim算法？&quot;">​</a></h2><p>普里姆算法从图中的任意一个顶点开始，**逐步将最近的顶点加入到正在构建的最小生成树中，直到所有的顶点都被加入为止。**这个过程中始终保持已经选择的顶点集合与剩余顶点集合之间的最短边被选择。通过一个具体的例子来说明普里姆算法（Prim&#39;s Algorithm）的流程会更加直观。假设我们有一个无向图，如下所示：</p><p><img src="'+c+'" alt=""></p><h2 id="prim算法的通俗解释" tabindex="-1">Prim算法的通俗解释 <a class="header-anchor" href="#prim算法的通俗解释" aria-label="Permalink to &quot;Prim算法的通俗解释&quot;">​</a></h2><p>Prim算法就像建桥工程师连接岛屿的过程，目标是花最少的钱让所有岛屿通车。比如有7个岛，每个岛之间修桥的成本不同，工程师会这样做：</p><ol><li><strong>随便选起点</strong>：比如先选1号岛当基地（这就像树的根）</li><li><strong>找最便宜的桥</strong>：看1号岛周围哪座桥最便宜，比如到2号岛只要1块钱，先修这座桥</li><li><strong>扩大基地范围</strong>：现在1、2号岛连起来了，再看这两个岛周围未连的岛中，哪座桥最便宜。比如发现2号岛到6号岛只要1块钱，接着修这座桥</li><li><strong>重复找最便宜</strong>：就像滚雪球，每次都用已经连通的岛做跳板，找连接新岛最便宜的桥，直到所有岛都连通</li></ol><p>整个过程像搭积木，每次只选当前最划算的积木块。工程师永远不选贵的桥，只挑当下最便宜的，这种&quot;贪小便宜&quot;的策略最后反而能省最多的钱。实际生活中，这种算法能帮快递员设计最短送货路线，或者帮探险家规划最短寻宝路径。</p><h2 id="prim算法操作步骤" tabindex="-1">Prim算法操作步骤 <a class="header-anchor" href="#prim算法操作步骤" aria-label="Permalink to &quot;Prim算法操作步骤&quot;">​</a></h2><ol><li><strong>初始化：选择一个起始顶点，假设选择顶点 A</strong></li></ol><p><img src="'+d+'" alt=""></p><ol><li><strong>从优先队列中取出距离最小的顶点 B:</strong> 在与A相连的边中A到B的边权最小，因此我们将A到B加入最小生成树。</li></ol><p><img src="'+u+'" alt=""></p><ol><li>**从优先队列中取出距离最小的顶点 ：**在与[A、B]相连的所有边中，权重最小的为BC=2，所以将C加入最小生成树</li></ol><p><img src="'+b+'" alt=""></p><ol><li>**从优先队列中取出距离最小的顶点 D：**在与[A、B、C]相连的所有边当中，权重最小的为AD=3，所以将D加入最小生成树。</li></ol><p><img src="'+q+'" alt=""></p><ol><li>**从优先队列中取出距离最小的顶点 E：**在与[A、B、C、D]相连的所有边当中，权重最小的为DE=8，所以将E加入最小生成树。</li></ol><p><img src="'+C+'" alt=""></p><ol><li>**从优先队列中取出距离最小的顶点 ：**在与[A、B、C、D、E]相连的所有边当中，权重最小的为EF=6，所以将F加入最小生成树。此时所有顶点都已在最小生成树中，算法结束。</li></ol><p><img src="'+k+'" alt=""></p><h2 id="克鲁斯卡尔算法-kruskal-s-algorithm" tabindex="-1">克鲁斯卡尔算法 (Kruskal&#39;s Algorithm) <a class="header-anchor" href="#克鲁斯卡尔算法-kruskal-s-algorithm" aria-label="Permalink to &quot;克鲁斯卡尔算法 (Kruskal&#39;s Algorithm)&quot;">​</a></h2><h2 id="什么是kruskal-s-算法" tabindex="-1">什么是Kruskal&#39;s 算法？ <a class="header-anchor" href="#什么是kruskal-s-算法" aria-label="Permalink to &quot;什么是Kruskal&#39;s 算法？&quot;">​</a></h2><p>克鲁斯卡尔算法则是从图的所有边中按权重从小到大排序，然后依次选择权重最小的边加入到最小生成树中，前提是这条边不会形成环路。这个过程一直持续到生成树包含了图中所有的顶点为止。</p><h2 id="kruskal算法的通俗解释" tabindex="-1">Kruskal算法的通俗解释 <a class="header-anchor" href="#kruskal算法的通俗解释" aria-label="Permalink to &quot;Kruskal算法的通俗解释&quot;">​</a></h2><p>Kruskal算法就像用最省钱的方法把所有村庄用道路连起来，而且不绕圈圈！具体来说，分三步走：</p><ol><li><strong>按价格排序</strong></li></ol><p>假设每个村庄是图上的点，连接它们的道路有不同造价（权重）。我们先把所有道路从便宜到贵排好队。</p><ol><li><strong>选最便宜的路</strong></li></ol><p>从最便宜的路开始检查。比如第一条路连接A村和B村，只要这两个村子还没被其他路连起来，就修这条路。这里有个小秘诀：用村长（并查集）记录每个村子的归属。如果两个村子的村长不同，说明它们还没连通，可以修路；如果村长相同，修这条路就会形成绕圈的路，不能修。</p><ol><li><strong>重复直到全连通</strong></li></ol><p>继续检查下一条便宜的路，直到所有村子都被连接。就像拼拼图，每次都用最便宜的零件，而且保证不出现多余的环。最后用的路数量总是比村子少1个（比如5个村子用4条路）。</p><p>整个过程就像玩闯关游戏：先整理道具（排序），然后按性价比使用道具（选边），还要用村长系统防止重复建设（避免环路），最终用最低成本完成任务！</p><h2 id="kruskal算法的操作步骤" tabindex="-1">Kruskal算法的操作步骤 <a class="header-anchor" href="#kruskal算法的操作步骤" aria-label="Permalink to &quot;Kruskal算法的操作步骤&quot;">​</a></h2><p>假设我们有一个具体的无向图，其中顶点用字母表示，边及其权重用数字表示。为了简化说明，我们假设有一个简单的例子：</p><p><img src="'+P+'" alt=""></p><ol><li><strong>将带权无向图的边按照权值大小的顺序存放到边集合中</strong></li></ol><p><img src="'+B+'" alt=""></p><ol><li><strong>构造一个不包含任何边的图</strong></li></ol><p><img src="'+A+'" alt=""></p><ol><li><strong>从边集合中取出一条最小的边AB，将B加入图中(这里需要判断不属于同一个连通分量)</strong></li></ol><p><img src="'+x+'" alt=""></p><ol><li><strong>从边集合中取出一条最小的边BC，这里C和AB不属于同一个连通分量，因此将C加入图中</strong></li></ol><p><img src="'+y+'" alt=""></p><ol><li><strong>从边集合中取出一条最小的边AD，这里D和ABC不属于同一个连通分量，因此将D加入图中</strong></li></ol><p><img src="'+D+'" alt=""></p><ol><li><strong>从边集合中取出一条最小的边BD，但是这里BD和ABCD属于同一个连通分量，所以BD不能加入图中</strong></li><li><strong>从边集合中取出一条最小的边CF，这里F和ABCD不属于同一个连通分量，因此将F加入图中</strong></li></ol><p><img src="'+f+'" alt=""></p><ol><li><strong>从边集合中取出一条最小的边EF，这里E和ABCDF不属于同一个连通分量，因此将E加入图中，结束</strong></li></ol><p><img src="'+S+'" alt=""></p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网2017】关于连通图的生成树，下列说法错误的是（ ）A. 生成树必须包含原图的所有顶点B. 生成树是原图的极小连通子图C. 生成树中边的数量等于顶点数减1D. 生成树可以通过删除原图中的任意一条边得到答案：D解析：生成树需要删除原图中的冗余边使其无环，但并非任意删除一条边都能得到生成树（可能破坏连通性）。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2016】以下关于Prim算法和Kruskal算法的描述，正确的是（ ）A. Prim算法适用于有向图，Kruskal算法仅适用于无向图B. 两种算法都基于贪心策略寻找最小生成树C. Kruskal算法的时间复杂度始终优于Prim算法D. Prim算法需要预先对所有边按权重排序答案：B解析：Prim和Kruskal均采用贪心策略，B正确。A错误（均适用于无向图）；C错误（时间复杂度取决于具体实现）；D错误（Kruskal需排序边，Prim不需要）。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【南方电网2020】关于强连通图，下列说法正确的是（ ）A. 强连通图仅存在于无向图中B. 强连通分量内部顶点间双向可达C. 非强连通的有向图无法分解为强连通分量D. 强连通图的邻接矩阵一定是对称矩阵答案：B解析：强连通分量内部顶点双向可达，B正确。A错误（强连通为有向图概念）；C错误（任何有向图均可分解为强连通分量）；D错误（有向图邻接矩阵不一定对称）。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家能源集团2019】关于强连通图，下列说法正确的是（ ）A. 强连通图仅存在于无向图中；B. 强连通分量内部顶点间双向可达；C. 非强连通的有向图无法分解为强连通分量；D. 强连通图的邻接矩阵一定是对称矩阵答案：B解析：强连通分量内部顶点双向可达，B 正确。A 错误（强连通为有向图概念）；C 错误（任何有向图均可分解为强连通分量）；D 错误（有向图邻接矩阵不一定对称</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2018】使用Kruskal算法求解最小生成树时，需避免以下哪种情况？（ ）A. 选择权重最小的边B. 形成环路C. 边的数量超过顶点数D. 顶点未被全部包含答案：B解析：Kruskal算法需避免环路，通过并查集判断是否属于同一连通分量。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2013】若一个无向连通图有7个顶点，其最小生成树中边的数量为（ ）A. 6B. 7C. 8D. 5答案：A解析：生成树的边数=顶点数-1，7个顶点对应6条边。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2018】以下关于 Prim 算法和 Kruskal 算法的描述，正确的是？A.Prim 算法适用于有向图，Kruskal 算法仅适用于无向图；B.两种算法都基于贪心策略寻找最小生成树；C.Kruskal 算法的时间复杂度始终优于 Prim 算法；D.Prim 算法需要预先对所有边按权重排序；答案：B；解析：Prim（从顶点扩展）和 Kruskal（从边排序选择）均通过贪心策略逐步构建最小生成树</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2015】使用 Kruskal 算法求解最小生成树时，需避免以下哪种情况？A.选择权重最小的边；B.形成环路；C.边的数量超过顶点数；D.顶点未被全部包含；答案：B；解析：Kruskal 通过并查集判断边的两个顶点是否属于同一连通分量，避免添加边形成环路</th></tr></thead></table>',93)])])}const v=t(z,[["render",K]]);export{U as __pageData,v as default};
